from neo4j import UnitOfWork

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(tx, *args, **kwargs):
            try:
                with tx.begin(isolation_level=UnitOfWork.READ_COMMITTED):
                    result = func(tx, *args, **kwargs)
                    tx.commit()
                    return result
            except Exception as e:
                tx.rollback()
                raise e
        if timeout is not None:
            wrapper.timeout = timedelta(seconds=timeout)
        return wrapper
    return decorator
