def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value."""

    def _ttl_cache(func):
        cache = {}
        lst = []
        timestamp = {}

        def _ttl_memoize(*args, **kwargs):
            key = func(*args, **kwargs)
            if key not in cache or (timestamp.get(key, 0) < timer() - ttl):
                result = func(*args, **kwargs)
                if len(cache) >= maxSize:
                    cache.pop(lst.pop(timestamp.pop(key)))
                lst.append(key)
                timestamp[key] = timer()
                cache[key] = result
            return cache[key]

        @functools.wraps(func)
        def ttl_wrapper(*args, **kwargs):
            return _ttl_memoize(*args, **kwargs)

        ttl_wrapper.maxsize = maxSize
        ttl_wrapper.ttl = ttl
        ttl_wrapper.timestamp = timestamp
        ttl_wrapper.lst = lst
        return ttl_wrapper

