def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if func is None:
            raise ValueError('The @ttl_cache decorator must be applied innermost of all decorators.')
        if not inspect.isfunction(func):
            raise ValueError('The @ttl_cache decorator must be applied to a function.')

        result_cache = {}
        lifetimes = {}

        def key_func(*args, **kwargs):
            return hash((args, frozenset(kwargs.items())))

        def update_cache(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in result_cache:
                current_time = timer()
                if (current_time - lifetimes[key]) > ttl:
                    del result_cache[key]
                    del lifetimes[key]
            if len(result_cache) >= maxsize:
                oldest_key = max(lifetimes, key=lifetimes.get)
                del result_cache[oldest_key]
                del lifetimes[oldest_key]

        def result(*args, **kwargs):
            key = key_func(*args, **kwargs)
            result_cache[key] = func(*args, **kwargs)
            lifetimes[key] = timer()
            return result_cache[key]

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in result_cache:
                return result_cache[key]
            return result(*args, **kwargs)

        return wrapper
