from functools import wraps, partial
from contextlib import contextmanager
import inspect

def key_factory(*args, **kwargs):
    return tuple(args + tuple(sorted(kwargs.items())))

def equal_args(*args, **kwargs):
    return args == args and kwargs == kwargs

def _memoized_call(fn, cache, *args, **kwargs):
    key = key_factory(*args, **kwargs)
    try:
        return cache[key]
    except KeyError:
        pass # key not found
    v = fn(*args, **kwargs)
    try:
        cache[key] = v
    except ValueError:
        pass # value too large
    return v

def memoized(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    if maxsize < 1:
        raise ValueError("maxsize must be positive")

    cache = {}
    if typed:
        cache_type = tuple
    else:
        cache_type = dict

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = key_factory(*args, **kwargs)
            if key in cache_type:
                return cache_type[key]
            result = fn(*args, **kwargs)
            if len(cache) >= maxsize:
                if typed:
                    evicted_key = max(cache_type, key=lambda k: k[0])
                else:
                    evicted_key = max(cache, key=lambda k: k[0])
                del cache[evicted_key]
            cache_type[key] = result
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = key_factory(*args, **kwargs)
            yield functools.partial(cache_type.__setitem__, key)
        wrapper.put = put

        def forget(*args, **kwargs):
            key = key_factory(*args, **kwargs)
            if key in cache_type:
                del cache_type[key]
        wrapper.forget = forget

        def clear():
            cache.clear()
        wrapper.clear = clear

        return wrapper

    return decorator
