def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def wrapper(fn):
        if cache is None:
            def cache_function(*args, **kwargs):
                return fn(*args, **kwargs)
        elif lock is None:
            def cache_function(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = fn(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def cache_function(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = fn(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(cache_function, fn)
    return wrapper
