def lfu_cache(maxsize=128, typed=False):
    def decorator(fn):
        if typed:
            cache = {}
        else:
            cache = {}
        count = defaultdict(int)

        @functools.wraps(fn)
        def memoize(*args, **kwargs):
            key = hash(args) + hash(kwargs)
            if key in cache:
                count[key] += 1
                return cache[key]
            result = fn(*args, **kwargs)
            cache[key] = result
            count[key] = 1
            if len(cache) > maxsize:
                min_count = min(count.values())
                least_frequent_keys = [key for key, count in cache.items() if count == min_count]
                for key in least_frequent_keys:
                    del cache[key]
        return memoize

    return decorator
