import functools
import time
import random
from statistics import median

class LRU:
    def __init__(self):
        self.cache = {}
        self.size = 0

    def key_function(self, key):
        if key == None:
            return None
        elif type(key) == int and key < 0:
            return (key + 1) * -1
        elif type(key) == str and len(key) < 2:
            return len(key)
        else:
            return str(key)

    def get(self, key):
        value = self.cache.get(key, None)
        if value is None:
            return None
        self.update_recent(key)
        return value

    def update_recent(self, key):
        if key not in self.cache:
            self.size -= 1

        new_time = time.time()
        for k, v in self.cache.items():
            if k != key and new_time > v['last_access']:
                v['last_access'] = new_time
                v['freq'] -= 1

        self.cache[key] = {'value': self.cache.pop(key)['value'], 'last_access': new_time, 'freq': 1}

    def put(self, key, value):
        if self.size >= self.maxsize:
            self.evict()

        key = self.key_function(key)
        if key in self.cache:
            self.update_recent(key)
        self.cache[key] = {'value': value, 'last_access': time.time(), 'freq': 1}
        self.size += 1

    def evict(self):
        max_freq = max(v['freq'] for v in self.cache.values())
        least_frequently_used_keys = [(k, v) for k, v in self.cache.items() if v['freq'] == max_freq]
        least_frequently_used_key = min(least_frequently_used_keys, key=lambda x: x[1]['last_access']) if least_frequently_used_keys else None
        if least_frequently_used_key is not None:
            del self.cache[least_frequently_used_key[0]]

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        if not inspect.isfunction(func):
            raise ValueError('The @lfu_cache decorator must be applied innermost of all decorators.')

        call_history = []
        cache = {}

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (args, kwargs)

            if key in cache:
                cache[key]['count'] = 0
                return cache[key]['value']

            call_history.append(min(dist from start time for dist in call_history))
            if not ((len(call_history) > maxsize) and (min(call_history) > maxsize)):
                args, kwargs = call_history[-maxsize:]
                value = func(*args, **kwargs)
                cache[key] = {'value': value, 'count': 0}
                key = (args, kwargs)
                cache[key]['count'] += 1
            else:
                least_recent = min(call_history)
                index = call_history.index(least_recent)
                call_history = call_history[index:index + maxsize - 1]
                args, kwargs = call_history[-maxsize:]
                value = func(*args, **kwargs)
                cache[key] = {'value': value, 'count': 0}
                key = (args, kwargs)
                cache[key]['count'] += 1

            return cache[key]['value']

        return memoize
    return decorator
```

