def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(fn):
        if fn is None:
            # We're being applied as a decorator factory; ie: the user has supplied args, like so:
            # >>> @lfu_cache(cache_factory=lru_cache)
            # ... def expensive_operation(user):
            # ...   pass
            # So we return a decorator with the user-supplied args curried in for the python decorator
            # machinery to use to wrap the upcoming func.
            #
            # NB: This is just a tricky way to allow for both `@lfu_cache` and `@lfu_cache(...params...)`
            # application forms.  Without this trick, ie: using a decorator class or nested decorator
            # function, the no-params application would have to be `@lfu_cache()`.  It still can, but need
            # not be and a bare `@lfu_cache` will work as well as a `@lfu_cache()`.
            return functools.partial(lfu_cache, maxsize=maxsize, typed=typed)
        if not inspect.isfunction(fn):
            raise ValueError('The @lfu_cache decorator must be applied innermost of all decorators.')

        if typed:
            memoized_results = {}
        else:
            memoized_results = LRU Cache(maxsize)

        @functools.wraps(fn)
        def update_cache(key, value):
            memoized_results[key] = value

        def lfu_update(key, value, count):
            memoized_results[key] = (value, count)

        def lfu_clear():
            memoized_results.clear()

        @functools.wraps(fn)
        def lfu_delete(key):
            lfu_update(key, None, 0)

        @functools.wraps(fn)
        def lfu_get(key, default=None):
            result, _, count = memoized_results.get(key, (default, 0, 0))
            if count > 0:
                lfu_update(key, result, count - 1)
            return result

        @functools.wraps(fn)
        def lfu_put(key, value):
            lfu_update(key, value, 1)

        @functools.wraps(fn)
        def lfu_contains(key):
            return key in memoized_results

        lfu_cache.update_cache = update_cache
        lfu_cache.lfu_update = lfu_update
        lfu_cache.lfu_clear = lfu_clear
        lfu_cache.lfu_delete = lfu_delete
        lfu_cache.lfu_get = lfu_get
        lfu_cache.lfu_contains = lfu_contains

        return update_cache
    return decorator
```

