@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if not isinstance(e, Exception):
        raise ValueError("e must be an Exception instance")

    if max_level == 0:
        return '.'

    ret = []
    frame_depth = 0
    tb = e.__traceback__
    while tb:
        if frame_depth >= max_level:
            return '...'
        frame = tb.tb_frame
        frame_depth += 1
        filename = frame.f_code.co_filename
        lineno = frame.f_lineno
        funcname = frame.f_code.co_name
        codeobj = frame.f_code

        if max_path_level == 0:
            return '...'

        for level in range(max_path_level):
            if level > 0:
                path, line, name, src = tb.co_filename, tb.co_line, tb.co_name, tb.co_src
            else:
                path, line, name, src = filename, lineno, funcname, codeobj.co_str

            if level > 0:
                ret.append('%s@%s:%s' % (path, line, name))
            else:
                ret.append('%s:%s:%s' % (path, line, name))
            if src is not None:
                ret.append('    %s' % src)
            if src is not None and not src.endswith('\n'):
                ret.append('    ')

        tb = tb.tb_next

    return '\n'.join(ret)
