from typing import List

def _legacy_mergeOrderings(orderings: List[List[str]]) -> List[str]:
    res = [[""] * len(orderings[0]) for _ in range(len(orderings))]
    for order in range(len(orderings)):
        for i in range(len(orderings[order])):
            for prev_ordering in range(order):
                if any(sorted(ordering[i]) >= sorted(ordering[prev_ordering])):
                    res[order][i] = res[prev_ordering][i]
    return ["".join(d) for d in res]
