def to_csv(self, separator=",", header=None):
        import csv

        # Convert graph's points to CSV
        points = self.points
        if not isinstance(points, list) or not all(isinstance(p, list) for p in points):
            raise ValueError("points must be a list of lists")

        if header is not None:
            csv_writer = csv.writer(open(self.path, "w+", newline='', encoding=self.encoding), delimiter=separator, quotechar='"')
            csv_writer.writerow(header)
        else:
            csv_writer = csv.writer(open(self.path, "w+", newline='', encoding=self.encoding), delimiter=separator, quotechar='"')

        for point in points:
            if not all(isinstance(coord, (int, float)) or coord is None for coord in point):
                raise ValueError("point must be a list of numbers or None")
            csv_writer.writerow([str(coord) for coord in point])

        print("Finished exporting CSV file")
