def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    for key, value in self.properties.items():
        if key == 'error':
            if isinstance(value, dict):
                if 'x_low' not in context.error:
                    context.error['x_low'] = {'x_high': None, 'index': None, 'index_max': None, 'x_low': None, 'x_middle': None}
                if isinstance(value['x_low'], bool):
                    context.error['x_low']['x_high'] = value['x_low']
                else:
                    context.error['x_low']['x_high'] = value['x_low']['x_high']
                context.error['x_low']['index'] = self._get_index(value['x_low'])
                context.error['x_low']['index_max'] = self._get_index(value['x_low']) + 1
                context.error['x_low']['x_low'] = self._get_value(value['x_low'])
                context.error['x_low']['x_middle'] = self._get_value(value['x_low'])
            else:
                context.error.append(value)
        else:
            if key.endswith('_high'):
                key = key[:-5]
            if key.endswith('_low'):
                key = key[:-5]
            if key.endswith('_middle'):
                key = key[:-7]
            if key.endswith('_max'):
                key = key[:-4]
            if key in context.value:
                if isinstance(context.value[key], dict):
                    if 'index' not in context.value[key]:
                        context.value[key]['index'] = None
                    if isinstance(value, bool):
                        context.value[key]['index'] = self._get_index(value)
                    else:
                        context.value[key]['index'] = self._get_index(value) + 1
                else:
                    context.value[key] = value
            elif isinstance(value, dict):
                context.value[key] = {'index': None}
