        if key in d2 and d1[key] != d2[key]:
            difference_dict[key] = d1[key]
        # Recurse if not yet reached maximum level or key is not a dict
        elif level != 0 and not isinstance(d1[key], dict):
            difference_dict[key] = d1[key]
        # Recursively call difference function if key is a dict
