def _validate_labels(labels):
    messages = []
    required_keys = set(labels.keys())
    for key, value in labels.items():
        if not isinstance(key, str):
            messages.append({'key': "Key must be a string"})
        if isinstance(key, str) and not re.match(r'^[a-zA-Z][a-zA-Z0-9]*$', key):
            messages.append({'key': "Label key '{}' does not match the regex ^[a-zA-Z][a-zA-Z0-9]*$".format(key)})
        if isinstance(value, list):
            expected_type = value[0]
            if not isinstance(value[0], isinstance):
                messages.append({'value': "Value for key '{}' must be of type {}".format(key, expected_type)})
            for item in value:
                result = _ValidateValue(item, expected_type)
                if not result:
                    messages.append({'value': "Invalid value '{}' for key '{}'".format(item, key)})
        elif not isinstance(value, isinstance):
            messages.append({'value': "Value for key '{}' must be of type {}".format(key, expected_type)})
    missing_keys = required_keys - set(labels.keys())
    if missing_keys:
        messages.extend([{'key': "Key '{}' is missing".format(key)} for key in missing_keys])
    return messages
