def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    """
    from krake.data.kubernetes.observer import ObserverEntry
    from krake.resource import K8sResource

    def default_observer_schema(resource_type):
        """Default observer schema for the given Kubernetes resource type."""
        return {
            'type': type(resource_type).__name__,
            'fields': {
                'name': {
                    'type': 'str',
                    'description': 'The name of the observer.'
                },
                'spec': {
                    'type': 'dict',
                    'description': 'The specification of the observer.'
                },
                'status': {
                    'type': 'dict',
                    'description': 'The status of the observer.'
                },
            }
        }

    for entry in app.spec.manifest:
        if not isinstance(entry, K8sResource):
            continue

        resource_name = entry.name
        resource_type = entry.resource_type

        default_schema = default_observer_schema(resource_type)

        # Assuming app.observer_schema is a dictionary where the keys are resource types
        if resource_type in app.observer_schema:
            continue

        # If default schema isn't in observer_schema add it
        app.observer_schema[resource_type] = default_schema
