        from jsonpointer import resolve_pointer

        # Create a dictionary to store the observed schema for each resource type
        observed_schemas = {}

        # Iterate over each non-empty resource type in the manifest
        for resource_type in [resource_type for resource_type in self.spec.manifest if resource_type]:
            # Fetch the controllable specification for the resource type
            controllable_spec = resolve_pointer(self.spec.for_resource(resource_type), 'spec')

            # Generate a default observer schema for the resource type
            observer_schema = {
                'type': 'object',
                'properties': {
                    'metadata': {
