import collections.abc as abc

def format(self, sql: abc.AnyStr, params: abc.Mapping[str, Any] | abc.Sequence[Any]) -> tuple[str, abc.Mapping[str, Any] | abc.Sequence[Any]]:
    if isinstance(params, abc.Mapping):
        # If in-style is named, params must be a dictionary
        if self.SQLParams.in_style:
            if not isinstance(params, dict):
                raise ValueError("For named parameter style, params must be a dictionary")
        else:
            # Otherwise, params must be a list
            if not isinstance(params, list):
                raise ValueError("For ordinal parameter style, params must be a list")
            # Convert sequence to dictionary if in-style is named
            if self.SQLParams.in_style:
                params = {k: v for v, k in enumerate(params)}
    else:
        # If not a dictionary or sequence, raise an error
        raise ValueError("Params must be a dictionary or sequence")

    # Convert params to list if it's a dictionary
    if isinstance(params, dict):
        params = list(params.items())

    # Return the formatted SQL and converted params
    return sql, params
