def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    spec_version = self.spec_version
    is_type_valid = True

    if extract_spec_version:
        inventory_type = inventory.get('type')
        if inventory_type is None:
            if self._log:
                self._log.error("Inventory type is missing")
                self._log.info("Setting spec_version to auto since type is missing...")
            spec_version = 'auto'
            is_type_valid = False
        elif inventory_type not in self.inventory_type_mapping:
            if self._log:
                self._log.error("Invalid inventory type %s", inventory_type)
                self._log.info("Setting spec_version to auto since invalid type...")
            spec_version = 'auto'
            is_type_valid = False
        elif inventory_type != self.inventory_type_mapping['auto']:
            # if we get here, then the type is valid, but the version is incorrect
            if self._log:
                self._log.error("Inventory type is %s, but version is %s", inventory_type, spec_version)
            is_type_valid = False

    # validate inventory data
    for key, value in inventory.items():
        if key not in self.safe_keys:
            # this key is not safe to validate, skip it
            continue

        if key == 'type':
            # if the key is 'type', we need to validate it separately
            if inventory_type == 'auto':
                if value is None:
                    if self._log:
                        self._log.error("Inventory type is missing and auto set to None")
                    spec_version = 'auto'
                    is_type_valid = False
                elif not isinstance(value, self.inventory_type_mapping['auto']):
                    if self._log:
                        self._log.error("Invalid inventory type %s", value)
                        self._log.info("Setting spec_version to auto since invalid type...")
                    spec_version = 'auto'
                    is_type_valid = False
            elif inventory_type == 'string':
                if not isinstance(value, str):
                    if self._log:
                        self._log.error("Type '%s' is supposed to be a string but is '%s'", inventory_type, type(value).__name__)
                    is_type_valid = False
            # if inventory_type is 'integer', 'float', 'boolean', or 'array', we only need to validate the schema
            elif inventory_type in ['integer', 'float', 'boolean', 'array']:
                # first validate the top-level schema
                if value.get('type') not in self.schema_type_mapping:
                    if self._log:
                        self._log.error("Invalid type '%s' in inventory sample", value['type'])
                    is_type_valid = False
                # then validate the contained schema if it exists
                if value.get('type') == 'array' and 'contained_type' in value:
                    if not isinstance(value['contained_type'], (type, Schema, Array, types.FunctionType)):
                        if self._log:
                            self._log.error("Unsupported field type contained by Array at {}.", path)
                        is_type_valid = False
        elif key == 'item_list':
            # if the key is 'item_list', we need to validate each item in the list separately
            for item in value:
                if not isinstance(item, self.item_type):
                    if self._log:
                        self._log.error("Invalid item of type %s in list", type(item).__name__)
                    is_type_valid = False
        else:
            # if the key is not 'type' or 'item_list', we need to validate its schema
            if key not in self.schema_mapping:
                if self._log:
                    self._log.error("Invalid field '%s' in inventory", key)
                    self._log.info("Setting spec_version to auto since field is invalid...")
                spec_version = 'auto'
                is_type_valid = False
            else:
                field_schema = self.schema_mapping[key]
                valid = field_schema.validate(value, self.item_name)
                if not valid:
                    if self._log:
                        self._log.error("Invalid field '%s' in inventory", key)
                    is_type_valid = False

    if inventory_type == 'string':
        # type 'string' should have a required default if defined
        if not is_type_valid and isinstance(inventory.get('default'), str):
            if self._log:
                self._log.error("Default for string field '%s' is not specified", key)
            is_type_valid = False

    if not is_type_valid:
        if self._log:
            self._log.error("Inventory validation failed with spec_version %s", spec_version)
        raise ArgumentError("Invalid inventory", spec_version)
