def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if hasattr(inventory, 'type') and inventory.type:
        try:
            if isinstance(inventory.type, Schema):
                # Nested documents cannot have validation
                if not set(inventory.type.keys()).issubset(set(['type', 'required', 'nullable', 'default'])):
                    raise SchemaFormatException("Unsupported field spec item at {}. Items: " + repr(inventory.type.keys()), inventory.type['path'])
            elif isinstance(inventory.type, Array):
                if not isinstance(inventory.type.contained_type, (type, Schema, Array, types.FunctionType)):
                    raise SchemaFormatException("Unsupported field type contained by Array at {}.", inventory.type['path'])

            elif not isinstance(inventory.type, type) and not isinstance(inventory.type, types.FunctionType):
                raise SchemaFormatException("Unsupported field type at {}. Type must be a type, a function, an Array or another Schema", inventory.type['path'])
        except KeyError as e:
            raise SchemaFormatException("Missing key '{}' in inventory type definition.", e) from e
    else:
        raise SchemaFormatException("Inventory type is missing or invalid.")
