def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialize a dictionary to store the mapping of logical paths to content files
    logical_path_map = {}

    # Iterate through each occurrence of the given version in the inventory
    for version_entry in inventory.values():
        if version_entry['version'] == version:
            # Iterate through each item in the version entry
            for item in version_entry['items']:
                # Get the physical path of the content file
                content_file_path = item['file']

                # Add the logical path to the dictionary if it's not already present
                if item['logical_path'] in logical_path_map:
                    # If the logical path already exists, add the content file path to the set
                    logical_path_map[item['logical_path']].add(content_file_path)
                else:
                    # If the logical path doesn't exist, create a new set with the content file path
                    logical_path_map[item['logical_path']] = {content_file_path}

    # Return the dictionary with the logical path map
    return logical_path_map
