def files_list(path):
    """
    Return all files at the given path.

    Args:
        path (str): The path to search for files.

    Returns:
        list of str: List of absolute file paths to the files in the path directory.
    """
    ret = []
    if isfile(path):
        ret.append(abspath(path))
    elif isdir(path):
        ret += [f for f in listdir(path) if isfile(f)]
        try:
            ret += [f for f in listdir(path + '/..') if isfile(f)]
        except OSError:
            pass
    else:
        raise FileNotFoundError(path)
    return ret

