class Element:
    def __init__(self, symbols):
        self.symbols = symbols.copy()

    def absorb(self, items):
        # Create economical parsers
        self._parser_positive = self.parser_from_symbols(*self.symbols)
        self._parser_negative = self.parser_from_symbols(*self.symbols)

        # Iterate over items
        out = sorted([symbol for symbol in items if symbol is not None], reverse=True)
        for item in items:
            # Negative absorption
            if item is None:
                out = [self._parser_negative(s) for s in out] or out
            # Absorption
            else:
                out = [self._parser_positive(s) | self._parser_negative(s) for s in out] or out
        return out

    def parser_from_symbols(self, *symbols):
        parser = ElementParser(symbols)
        res, unused = parser.parse_known_args(None)
        return getattr(res, 'symbols')
