from typing import List, Tuple

def absorb(self, args: List[str]) -> List[str]:
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    newargs = []
    for arg in args:
        if "&" in arg and "|" in arg:
            L, R = arg.split("&")
            if L == "~" + R:
                newargs.append("".join(["~~" * (len(R) - 1), L, R]))
            elif R == "~" + L:
                newargs.append("".join(["~~~~" * (len(L) - 1), L, R]))
            else:
                newargs.append("".join([L, '_', R]))
        elif "&" in arg:
            newargs.append("~~" * len(arg))
        elif "|" in arg:
            newargs.append("~~~~" * len(arg))
        else:
            newargs.append(arg)
    return newargs
