def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    absorbed = []
    negative_absorbed = []

    for arg in args:
        if arg.startswith('-'):
            if arg[1:] in absorbed:
                absorbed.pop(absed.index(arg[1:]))
            else:
                negative_absorbed.append(arg[1:])
        else:
            if arg in negative_absorbed:
                negative_absorbed.remove(arg)
            else:
                absorbed.append(arg)

    return absorbed, negative_absorbed
