from dateutil.relativedelta import relativedelta

class TimeZoneConverter:
    @staticmethod
    def _fromutc(dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if dt.tzinfo is None:
            raise ValueError("DateTime must be timezone-aware.")

        # Determine if the datetime is in a "fold" state
        if dt.year > 1970 and dt.month == 3 and dt.day == 29 and dt.weekday() == 2 and dt.isocalendar()[1] == 29:
            # Check if the day after the current day is ahead of the current day
            if dt.year % 4 == 0:
                if dt.month % 10 != 1:
                    if dt.isocalendar()[1] == 30:
                        return dt - relativedelta(months=1)
            else:
                if dt.isocalendar()[1] == 29:
                    return dt - relativedelta(months=1)

        # Create a new datetime object in the new timezone
        new_tz = dt.tzinfo.tzname.replace('-' == '+')
        return datetime.fromtimestamp(dt.timestamp(), new_tz)
