        inventory_dir = os.path.join(self.unicycle_dir, version_dirs[i])
        if not os.path.exists(inventory_dir):
            raise ValueError(f"Version directory '{version_dirs[i]}' does not exist.")
        if not os.path.isdir(inventory_dir):
            raise ValueError(f"Version directory '{version_dirs[i]}' is not a directory.")
        file_path = os.path.join(inventory_dir, 'version.txt')
        if not os.path.exists(file_path):
            raise ValueError(f"Version file '{file_path}' does not exist in version directory '{version_dirs[i]}'.")
        try:
            with open(file_path, 'r') as f:
                version = f.read().strip()
        except FileNotFoundError:
            raise ValueError(f"Version file '{file_path}' could not be read.")
        if version.strip() == '':
            raise ValueError(f"Version file '{file_path}' is empty.")
        existing_inventory = self.get_existing_inventory(version)
        if existing_inventory is None:
            self.set_existing_inventory(version, inventory_dir)
        else:
            if existing_inventory == inventory_dir:
                continue
            raise ValueError(f"Inventory specified for version '{version}' already exists in {existing_inventory}.")
        self.update_comparison_inventory_dict(version, inventory_dir)
