def default_merge(existing, new):
    if isinstance(existing, dict):
        if isinstance(new, dict):
            result = {k: default_merge(existing.get(k, {}), new.get(k, {})) for k in existing}
            result.update({k: new[k] for k in new if k not in existing})
        else:
            result = {k: new[k] for k in existing}
    elif isinstance(existing, list):
        if isinstance(new, list):
            result = existing + new
        else:
            result = existing + [new]
    else:
        result = new

    return result
