def parse_subparser_arguments(unparsed_arguments, subparsers):
    result_parsers = {}
    remaining_args = List(str)

    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            match = parser.match(arg)
            if match:
                if name in result_parsers:
                    result_parsers[name].update(match.namespace)
                else:
                    result_parsers[name] = match.namespace
                remaining_args.extend(match.args)
                remaining_args.extend(match.kwargs)
                break
        else:
            remaining_args.append(arg)

    return result_parsers, remaining_args
