def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    def _arguments(ctx):
        """Return� 'option' or 'argument' string for each param.

        For example, get_arguments(ctx) might return ['option', 'argument']
        """
        ctx = ctx.parent
        main = ctx.command
        if ctx.command_name:
            command = main.get_command(ctx, ctx.command_name)
            if not command:
                return
        else:
            command = main

        types = ["option", "argument"]
        all_params = sorted(
            command.get_params(ctx), key=lambda p: types.index(p.param_type_name)
        )

        def get_name(param):
            return max(param.opts, key=len)

        for param in all_params:
            if param.param_type_name == "option":
                option = get_name(param)
                same_dest = [
                    get_name(p) for p in all_params if p.name == param.name
                ]
                if same_dest:
                    option = "({})".format(" ".join(same_dest)) + option
            elif param.param_type_name == "argument":
                option = get_name(param)
            click.echo(option)
    _arguments()
