def parse_subparser_arguments(unparsed_arguments, subparsers):
    collected_results = {}
    remaining_arguments = []

    for subparser_name, subparser in subparsers.items():
        # Check if the subparser has any help message (should be present in argparse.ArgumentParser documentation)
        if not subparser.get_help():
            # This subparser does not need to parse any arguments
            continue

        # Scan the remaining arguments until they exhaust
        while unparsed_arguments:
            argument = unparsed_arguments.pop(0)
            # Parse the argument for the current subparser using the parser of the current subparser
            if argument in subparser._options and subparser._options[argument]:
                # If the argument is defined for the subparser, parse it
                parsed_value = subparser._options[argument]
                collected_results[subparser_name][argument] = parsed_value
            else:
                # If the argument is not defined for the subparser, mark it as remaining
                remaining_arguments.append(argument)

    return collected_results, remaining_arguments
