def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if size.endswith("B"):
        bytes_size = int(size[:-1])
    elif size.endswith("K"):
        bytes_size = round(int(size[:-1]) * 1024, 2)
    elif size.endswith("M"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024, 2)
    elif size.endswith("G"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024 * 1024, 2)
    elif size.endswith("T"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024 * 1024 * 1024, 2)
    elif size.endswith("P"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024 * 1024 * 1024 * 1024, 2)
    elif size.endswith("E"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024 * 1024 * 1024 * 1024 * 1024, 2)
    elif size.endswith("Z"):
        bytes_size = round(int(size[:-1]) * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024, 2)
    elif size.endswith("Y"):
        bytes_size = int(size[:-1])
    else:
        raise ValueError("Invalid file size format. Supported formats are B, K, M, G, T, P, E, Z, Y")

    return bytes_size
