import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = ' POSIX' if sys.platform == 'darwin' or sys.platform.startswith(('linux', 'bsd')) else 'Windows/CMD'
    elif platform == 1:
        platform = ' POSIX'
    elif platform == 0:
        platform = 'Windows/CMD'
    else:
        raise ValueError("Invalid platform '%s'" % platform)

    if platform == 'POSIX':
        command = '/bin/sh'
    elif platform == 'Windows/CMD':
        command = 'cmd.exe'

    pattern = r"'[(\s|\\S)+]'|\"[(\s|\\S)+\"]|\*\**+|&&|\|\|\~|\!\"|[\(\)\[\]\{\']+|\#|[:,\s]+|[^\\n\']+'
    tokens = re.findall(pattern, s)
    return [token.replace('"', '').replace("'", '') for token in tokens]
