static str[] split(String s, int platform = -1) {
    if (platform < 0 && platform >= 2) {
        platform = platform ? 0 : 1;
    }

    StrArrayBuilder builder = StrArrayBuilder.create();

    if (platform == 0) {
        Pattern linuxPattern = Pattern.compile("(?: ([^ \'"\\\\]+)|''|\\"")[\'\"]*");
        Matcher match = linuxPattern.matcher(s);

        while (match.find()) {
            String matchString = match.group();
            if (matchString.equals("\\'") || matchString.equals("\\\"")) {
                builder.append("\\");
            }

            builder.append(matchString);
            if (matchString.length() > 0 && matchString.charAt(matchString.length() - 1) == '.') {
                builder.append(\' \');
            }
        }
    } else {
        Pattern windowsPattern = Pattern.compile("(?: ([^ \'"\\\\]+)|''|\\"")[\'\"]*");
        Matcher match = windowsPattern.matcher(s);

        while (match.find()) {
            String matchString = match.group();
            if (matchString.equals("\\'") || matchString.equals("\\\"")) {
                builder.append("\\");
            }

            builder.append(matchString);
            if (matchString.length() > 0 && matchString.charAt(matchString.length() - 1) == ' ') {
                builder.append(\' \');
            }
        }
    }

    return builder.toArray();
