    def git(args, error_message, cwd=None, **error_kwargs):
        try:
            output, status = subprocess.run(args, check=True, text=True, capture_output=True, cwd=cwd)
        except subprocess.CalledProcessError as e:
            error_kwargs['output'] = e.stderr
            error_kwargs['directory'] = cwd
            raise HarpoonError(error_message, **error_kwargs)
        return output

    git_command = ['git', 'ls-files', '--others', '--exclude-standard', '--']
    for file_path in ignored:
        git_command.append(file_path)

    output = git(git_command, "Failed to get list of ignored files")
    files = [file.strip() for file in output.splitlines()]
    files = sorted(files)
    return ','.join(files)

