def find_roots(self, graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    predicates = {graph.predicate for subject, predicate, object in graph}
    if prop not in predicates:
        raise ValueError("Provided predicate not found in graph")

    def get_root_distance(graph, subject, inner_set):
        for object in graph.objects(subject, prop):
            if object not in inner_set:
                inner_set.add(object)
                get_root_distance(graph, object, inner_set)
        return inner_set

    if roots is None:
        roots = set()
    for node in graph.subjects(prop RDF.type):
        if find_roots(graph, prop, set()).uion_with(roots) == nodes:
            roots.add(node)
    return roots

