import logging
def load_configurations(config_filenames, overrides=None, resolve_env=True):
    results = {}
    errors = []
    for filename in config_filenames:
        log_file = os.path.abspath(filename)
        if not os.path.exists(log_file):
            logging.error(f"Config file {filename} does not exist. Skipping...")
            continue

        parsed_config = {}
        parser = configparser.ConfigParser()
        try:
            parser.read(log_file)
            for section in parser.sections():
                parsed_config[section] = dict(parser[section])
        except Exception as e:
            logging.error(f"Error reading config file {filename}: {e}")
            errors.append(logging.LogRecord('error', logging.ERROR, __file__, 0, f"Error reading config file {filename}: {e}", traceback.format_exc()))
        else:
            results[filename] = parsed_config

    if overrides is not None:
        for key, value in overrides.items():
            results[value] = overrides[key]

    return results, errors
