@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    def version_tuple_checker(func, version_tuple):
        if not isinstance(version_tuple, tuple):
            name = func.__name__
            raise TypeError(f'Function {name} expected tuple, got {type(version_tuple).__name__} instead.')
        else:
            # Perform any additional type checks or version validation here
            pass

    if protocol_version is None:
        all_protocols = cls.all_supported_protocols()
    else:
        version_tuple_checker(cls.protocol_handlers, protocol_version)
        all_protocols = {protocol_version: cls.get_handler_for_version(protocol_version)}

    handlers_by_version = {}
    for protocol, handler_class in all_protocols.items():
        handler_class._protocol_version = protocol
        handlers_by_version[protocol] = handler_class
    return handlers_by_version
