def _verify(iface, candidate, tentative=False, vtype=None):
    # Make sure the candidate claims that it provides the interface using iface.providedBy (unless tentative is True, in which case this step is skipped). This means that the candidate's class declares that it implements <zope.interface.implementer> the interface, or the candidate itself declares that it provides <zope.interface.provider> the interface
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate does not provide the interface")

    # Make sure the candidate defines all the necessary methods
    for m in iface.iter_methods():
        if not hasattr(candidate, m.zope.interface.IMETHOD[m]):
            raise zope.interface.Invalid("Candidate does not define the method %s" % m)
        if not m.is_function():
            raise zope.interface.Invalid("Method %s is not a function" % m)
        if not hasattr(candidate, m.parameters):
            raise zope.interface.Invalid("Method %s does not have a parameter map" % m)

    # Make sure the methods have the correct signature (to the extent possible)
    for m in iface.iter_methods():
        method = getattr(candidate, m.zope.interface.IMETHOD[m])
        for name, desc in m.parameters.items():
            if name in kwargs and desc['type'] != type(kwargs[name]):
                raise zope.interface.Invalid("Method parameter %s does not match the specified type" % name)

    # Make sure the candidate defines all the necessary attributes
    for at in iface.iter_attributes():
        if name not in candidate:
            raise zope.interface.Invalid("Candidate does not define the attribute %s" % at)
        if not at.impliedBy():
            raise zope.interface.Invalid("Attribute %s is not implied by a qualifier" % at)

