def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is not None:
        return explicit_mc

    base_mclasses = set()
    for base in bases:
        try:
            base_mclass = base.extends("bases")
            if base_mclass:
                base_mclasses.add(base_mclass)
        except AttributeError:
            continue

    # If no explicit __metaclass__ is specified, use the metaclass of the base with the most subclasses
    base_counts = {}
    for base_mclass in base_mclasses:
        base_counts[base_mclass] = sum(1 for base in bases if base.extends("bases").name == base_mclass.name)

    if base_counts:
        return sorted(base_counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
    else:
        return type
