from dateutil.tz import tzutc

ISO8601_FORMAT = "%Y-%m-%dT%H:%M:%SZ"
ISO8601_FORMAT_MICROSECONDS = "%Y-%m-%dT%H:%M:%S.%fZ"
ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
DIGIT = "1234567890"
SEPARATOR = "T"

def isoparse(self, dt_str):
    dt_str = str(dt_str)
    offset = None

    # Split input string into date and time parts if it contains a separator
    parts = dt_str.split(SEPARATOR)
    if len(parts) > 2:
        raise ValueError("Input string is too complex to parse correctly")

        # Parse date part
        date_str = parts[0]
        parts = date_str.split("-")
        if len(parts) != 3:
            raise ValueError("Invalid date format")

        try:
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])
            dt = datetime.datetime(year, month, day, tzinfo=tzutc())
        except ValueError:
            raise ValueError("Invalid date value in input string")

        # Assign time part
        if len(parts) == 3:
            time_str = parts[1]
        elif len(parts) == 2:
            time_str = parts[0]
        else:
            time_str = "00:00"

        # Parse time part
        parts = time_str.split(":")
        if len(parts) != 2:
            raise ValueError("Invalid time format")

        try:
            hour = int(parts[0])
            minute = int(parts[1])
        except ValueError:
            raise ValueError("Invalid time value in input string")

        try:
            if len(parts) == 3:
                # Parse sub-second part
                seconds, subseconds = parts[2].split(".")
                dt = dt.replace(hour=hour, minute=minute, second=int(seconds), microsecond=int(subseconds) * 1000)
            else:
                dt = dt.replace(hour=hour, minute=minute)
        except ValueError:
            raise ValueError("Invalid sub-second value in input string")

    # Parse offset part if present
    if dt_str.endswith("Z"):
        offset = "Z"
    elif dt_str.endswith("+" or dt_str.endswith("-")):
        parts = dt_str.split(dt_str[-1])
        offset = dt_str[-1]
        try:
            hours = int(parts[0])
            minutes = int(parts[1])
            if len(parts) == 3:
                seconds, subseconds = parts[2].split(".")
                dt = dt.replace(second=int(seconds), microsecond=int(subseconds) * 1000)
        except ValueError:
            raise ValueError("Invalid offset value in input string")

    # Return parsed datetime object
    if offset == "Z":
        return dt.tzinfo.localize(dt)
    else:
        return dt
