from dateutil import parser

def make_datetime(dt):
    if isinstance(dt, datetime.datetime):
        return dt
    if isinstance(dt, list):
        dt = 'T'.join(dt)
    if isinstance(dt, basestring):
        if len(dt) <= len('2000-01-01'):
            return (datetime.datetime
                    .strptime(dt, '%Y-%m-%d')
                    .replace(tzinfo=UTC))
        else:
            try:
                parsed = isodate.parse_datetime(date)
            except ValueError:
                # e.g. '2012-01-10 12:13:14Z' becomes '2012-01-10T12:13:14Z'
                parsed = isodate.parse_datetime(
                    re.sub('(\d)\s(\d)', r'\1T\2', date)
                )
            if not parsed.tzinfo:
                parsed = parsed.replace(tzinfo=UTC)
            return parsed
    raise ValueError("date not a parsable string")

def make_tz_aware(dt, tz='UTC', is_dst=None):
    dt = make_datetime(dt)
    if not isinstance(dt, (list, datetime.datetime, datetime.date, datetime.time, pd.Timestamp)):
        return dt
    try:
        tz = dt.tzinfo or tz
    except (ValueError, AttributeError, TypeError):
        pass
    try:
        tzstr = str(tz).strip().upper()
        if tzstr in TZ_ABBREV_NAME:
            is_dst = is_dst or tzstr.endswith('DT')
            tz = TZ_ABBREV_NAME.get(tzstr, tz)
    except (ValueError, AttributeError, TypeError):
        pass
    try:
        tz = pytz.timezone(tz)
    except (ValueError, AttributeError, TypeError):
        pass
    try:
        return tz.localize(dt, is_dst=is_dst)
    except (ValueError, AttributeError, TypeError):
        pass
    # could be datetime.time, which can't be localized. Instaed `replace` the TZ
    # don't try/except in case dt is not a datetime or time type -- should raise an exception
    if not isinstance(dt, list):
        return dt.replace(tzinfo=tz)

def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.

    .. doctest::

        >>> from dateutil.tz import tzoffset
        >>> from dateutil.parser import parse
        >>> from dateutil.utils import default_tzinfo
        >>> dflt_tz = tzoffset("EST", -18000)
        >>> print(default_tzinfo(parse('2014-01-01 12:30 UTC'), dflt_tz))
        2014-01-01 12:30:00+00:00
        >>> print(default_tzinfo(parse('2014-01-01 12:30'), dflt_tz))
        2014-01-01 12:30:00-05:00

    :param dt:
        The datetime on which to replace the time zone

    :param tzinfo:
        The :py:class:`datetime.tzinfo` subclass instance to assign to
        ``dt`` if (and only if) it is naive.

    :return:
        Returns an aware :py:class:`datetime.datetime`.
    """
    dt = make_datetime(dt)
    if not isinstance(dt, datetime.datetime):
        return dt
    if dt.tzinfo:
        return dt
    return dt.replace(tzinfo=tzinfo)
