def find_tags(text, replacer=None):
    # Create a stack to keep track of nested code blocks
    stack = []

    # Split the text into lines and iterate through them
    lines = text.split('\n')
    for i, line in enumerate(lines):
        # Check if the line is a code block
        if line.lstrip().startswith('```'):
            if line.rstrip().endswith('```'):
                is_code_block = True
            else:
                is_code_block = False
        else:
            if is_code_block:
                # Start of a nested code block
                stack.append(i)
            elif is_code_block and stack and lines[stack[-1]].rstrip().endswith('```'):
                # End of the current code block
                stack.pop()

        # If a tag is found outside a code block
        if is_code_block is False and ': ' in line:
            tag, content = line.split(': ', 1)
            # Don't add the tag if it starts with a space
            if tag.strip():
                if replacer:
                    content = replacer(tag.strip())
                    line = ': '.join([tag, content])
                tags.add(tag.strip())

    # Combine the text with the inserted tags and return the list of tags and the modified text
    modified_text = '\n'.join(lines)
    return tags, modified_text
