def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags_found = set()

    lines = text.split('\n')

    for i in range(len(lines)):
        if i > 0:
            prev_line = lines[i-1]
        else:
            prev_line = ""

        if i < len(lines)-1:
            next_line = lines[i+1]
        else:
            next_line = ""

        line = lines[i]

        if ':' in line:
            index = line.index(':')
            tag_string = line[index+1:]

            if tag_string.strip().startswith('#'):
                tags_found.add(tag_string.strip())

            if replacer is not None:
                tags_found.add(replacer(tag_string.strip()))

            if ': ' in line:
                index = line.index(': ')
                tag_string = line[index+2:]

                if tag_string.strip().startswith('#'):
                    tags_found.add(tag_string.strip())

                if replacer is not None:
                    tags_found.add(replacer(tag_string.strip()))

    return tags_found, text

