    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        data = json.loads(document)

    if "xmpp_handle" in data:
        return {'xmpp_handle': data['xmpp_handle']}
    elif "weburi" in data:
        if 'hf' in data['weburi']:
            hf_link = [link for link in data['weburi']['hf'] if has_required_parameter(link, "address")][0]
            return {'hcard_url': hf_link.get("address", hf_link.get("uri"))}
    elif "link" in data:
        for link in data["link"]:
            if "protocol" in link and link["protocol"] == "https" and "rel" in link and link["rel"] == "http://xmlns.webfinger.net/rel/profile-page":
                return {'hcard_url': link.get("template", link.get("uri"))}

    return {}

def has_required_parameter(link, name):
    for parameter in link.get("parameter", []):
        if parameter.get("name") == name:
            return True
    return False

