class EncryptedPayload:
    @staticmethod
    def get_iv_key_encrypter():
        iv = get_random_bytes(16)
        key = generate_random_aes_key()
        encrypter = PKCS1_v1_5.new(RSA.import_key(b'-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA...\n-----END PUBLIC KEY-----\n'))
        return iv, key, encrypter

    @staticmethod
    def get_aes_key_json(iv, key):
        return {"iv": iv.hex(), "key": key.hex()}

    @staticmethod
    def decrypt(encrypted_json):
        iv = bytes.fromhex(encrypted_json["iv"])
        key = bytes.fromhex(encrypted_json["key"])
        decrypter = PKCS1_v1_5.new(RSA.import_key(b'-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA...\n-----END PUBLIC KEY-----\n'))
        encrypted = bytes.fromhex(encrypted_json["data"])
        decrypted = decrypter.decrypt(encrypted)
