def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        raise IRValidatorException("Spec content argument must be supplied")
    spec = yaml.safe_load(spec_content)
    required_fields = set(field['name'] for field in spec if field.get('required', False))
    missing_fields = required_fields - {field['name'] for field in spec if 'value' in field}
    if missing_fields:
        msg = "Missing mandatory fields: {}".format(', '.join(missing_fields))
        raise IRValidatorException(msg)
    doc = {}
    for field in spec:
        if field['required']:
            if 'value' not in field:
                msg = "Missing mandatory field: {}".format(field['name'])
                raise IRValidatorException(msg)
            doc[field['name']] = field['value']
        else:
            doc[field['name']] = None
    return doc
