def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    def resolve_include(node):
        key, value = node.split(':')
        if key == 'include':
            if value in self.groups:
                return resolve_include(self.groups[value])
            else:
                raise ValueError(f"Group '{value}' does not exist in the specification.")
        return node

    nodes = parser_dict.get('_definitions', {}).values()
    while any('[include]' in node for node in nodes):
        for node in nodes:
            if '[include]' in node:
                include_node = resolve_include(node)
                if include_node in nodes:
                    nodes.append(include_node)
                nodes.remove(node)
                break

    return parser_dict
