def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    from collections import Counter
    from copy import deepcopy

    conditional_args = Counter()
    option_names = {opt.index: opt.name for opt in options_spec}

    for arg in args:
        if arg.name in self.required_if and arg.value == 'true':
            conditional_args[arg.index] = arg.name
        elif arg.name in self.required_if and arg.value == 'false':
            conditional_args[arg.index] = option_names.get(arg.index)
        elif arg.value in self.required_args:
            conditional_args[arg.index] = arg.name

    if self.required_if:
        for idx, name in conditional_args.items():
            if idx not in self.required_if:
                del conditional_args[idx]

    return list(conditional_args.values())
