    if not extra_vars:
        return vars_dict

    extended_vars = vars_dict.copy()
    for extra in extra_vars:
        for key, value in extra.items():
            if key in extended_vars:
                extended_vars[key] = {**extended_vars[key], key: value}
            else:
                extended_vars[key] = {key: value}

    return extended_vars
```

