            playbook = self._get_ansible_playbook(self.playbooks.converge, **kwargs)
        else:
            playbook = self._get_ansible_playbook(playbook, **kwargs)

        return playbook.execute()

    def callPlaybook(self, playbook, ansible_args, wait=True, tags=["all"]):
        playbook = os.path.join(self.playbooks, playbook)  # Path to playbook being executed
        verbosity = "-vvvvv" if logger.isEnabledFor(logging.DEBUG) else "-v"
        command = ["ansible-playbook", verbosity, "--tags", ",".join(tags), "--extra-vars"]
        command.append(" ".join(["=".join(i) for i in ansible_args.items()]))  # Arguments being passed to playbook
        command.append(playbook)

        logger.debug("Executing Ansible call `%s`", " ".join(command))
        p = subprocess.Popen(command)
        if wait:
            p.communicate()
            if p.returncode != 0:
                # FIXME: parse error codes
