import os

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""

    if path.startswith(root):
        new_path = path[len(root):]
        if new_path:
            return new_path
        else:
            raise FileNotFoundError("Root not found in path")
    else:
        raise ValueError("Path already starts with root")
